//import './App.css';
import 'bootstrap/dist/css/bootstrap.min.css';
import { Button } from 'reactstrap';
import { Component } from 'react';

class App extends Component {
    constructor(props) {
        super(props);
        this.state = {
            listaBotones: Array(9).fill(null).map(e => Array(9).fill("-")),
            listaColores: ["primary", "danger"],
            turno: true,
            jugable: true,
        }
    }


    render() {
        return (
            <div className="App">
                <MapaBotones botones={this.state.listaBotones} colores={this.state.listaColores} />
            </div>
        );
    }
}

const MapaBotones = (props) => {
    // este componente visualiza todos los botones del juego
    // parametros listaBotones
    // evitar warnings por keys
    let lista = [];
    props.botones.map((fila, i) => {
        //console.log(fila)
        fila.map((columna, j) => {
            if (columna == "-") {
                lista.push(<Button key={i * 10 + j} outline onClick={() => console.log("Columna: " + j)}>{"   "}</Button>)
            } else {
                lista.push(<Button key={i * 10 + j} color={columna}>{"   "}</Button>)
            }
        })
        lista.push(<br key={"br" + i} />)
    })
    return (
        lista
    )
}

